{
  "claims": [
    {
      "claim_text": "During a full sync, the master saves an RDB file in the background.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 describes the master starting a background saving process to produce an RDB file during the synchronization process.",
      "citations": [
        {
          "index": 0,
          "quote": "The master starts a background saving process to produce an RDB file."
        }
      ]
    },
    {
      "claim_text": "While saving the RDB file in the background, the master buffers new write commands received from clients.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states that at the same time the master starts buffering all new write commands received from clients.",
      "citations": [
        {
          "index": 0,
          "quote": "At the same time it starts to buffer all new write commands received from the clients."
        }
      ]
    },
    {
      "claim_text": "After the background saving is complete, the master transfers the file to the replica.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states that when background saving is complete, the master transfers the database file to the replica.",
      "citations": [
        {
          "index": 0,
          "quote": "When the background saving is complete, the master transfers the database file to the replica, which saves it on disk, and then loads it into memory."
        }
      ]
    },
    {
      "claim_text": "The master then sends the buffered commands to the replica.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states the master will then send all buffered commands to the replica.",
      "citations": [
        {
          "index": 0,
          "quote": "The master will then send all buffered commands to the replica."
        }
      ]
    },
    {
      "claim_text": "Diskless replication is controlled by the repl-diskless-sync configuration parameter.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 states diskless replication can be enabled using the repl-diskless-sync configuration parameter.",
      "citations": [
        {
          "index": 1,
          "quote": "Diskless replication can be enabled using the `repl-diskless-sync` configuration parameter."
        }
      ]
    },
    {
      "claim_text": "Since Redis 7.0, diskless replication is enabled by default.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages do not mention Redis 7.0 or a default-enabled state for diskless replication.",
      "citations": []
    },
    {
      "claim_text": "Replicas replicate keys with expires correctly even when Lua scripts alter them.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 directly states replicas correctly replicate keys with expires even when altered using Lua scripts.",
      "citations": [
        {
          "index": 2,
          "quote": "Redis replicas correctly replicate keys with expires, even when such keys are altered using Lua scripts."
        }
      ]
    },
    {
      "claim_text": "Replicas do not expire keys themselves.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 states replicas do not expire keys and instead wait for masters to expire them.",
      "citations": [
        {
          "index": 3,
          "quote": "Replicas don't expire keys, instead they wait for masters to expire the keys."
        }
      ]
    },
    {
      "claim_text": "Replicas wait for the master's DEL commands.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 states replicas wait for masters to expire keys, and that the master synthesizes a DEL command transmitted to replicas when it expires or evicts a key.",
      "citations": [
        {
          "index": 3,
          "quote": "Replicas don't expire keys, instead they wait for masters to expire the keys. When a master expires a key (or evict it because of LRU), it synthesizes a `DEL` command which is transmitted to all the replicas."
        }
      ]
    },
    {
      "claim_text": "Redis Sentinel needs at least three instances to reach a reliable quorum.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages do not mention Redis Sentinel or quorum requirements.",
      "citations": []
    },
    {
      "claim_text": "Once promoted, a replica expires keys independently.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 4 states that once a replica is promoted to a master it starts to expire keys independently.",
      "citations": [
        {
          "index": 4,
          "quote": "Once a replica is promoted to a master it will start to expire keys independently, and will not require any help from its old master."
        }
      ]
    },
    {
      "claim_text": "The replication section of INFO and the ROLE command on a master show replicas as having the IP address they use to connect to the master.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 states the ROLE command and the replication section of INFO, when issued on a master, show replicas as having the IP address they use to connect to the master.",
      "citations": [
        {
          "index": 5,
          "quote": "the `ROLE` command, and the replication section of the `INFO` output, when issued into a master instance, will show replicas as having the IP address they use to connect to the master"
        }
      ]
    },
    {
      "claim_text": "Behind NAT, that address may differ from the logical address clients should use.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 states that in environments using NAT the connection address may differ from the logical address clients should use.",
      "citations": [
        {
          "index": 5,
          "quote": "in environments using NAT may be different compared to the logical address of the replica instance (the one that clients should use to connect to replicas)."
        }
      ]
    },
    {
      "claim_text": "Since Redis 3.2.2, a replica can announce a different IP and port.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 states that since Redis 3.2.2 it is possible to force a replica to announce an arbitrary pair of IP and port to the master.",
      "citations": [
        {
          "index": 6,
          "quote": "To fix both issues, it is possible, since Redis 3.2.2, to force a replica to announce an arbitrary pair of IP and port to the master."
        }
      ]
    },
    {
      "claim_text": "The ROLE command returns replication offsets.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states ROLE provides replication status together with replication offsets.",
      "citations": [
        {
          "index": 7,
          "quote": "Another more computer-friendly command is `ROLE`, that provides the replication status of masters and replicas together with their replication offsets, list of connected replicas and so forth."
        }
      ]
    },
    {
      "claim_text": "The ROLE command returns the list of connected replicas.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states ROLE provides the list of connected replicas among other information.",
      "citations": [
        {
          "index": 7,
          "quote": "Another more computer-friendly command is `ROLE`, that provides the replication status of masters and replicas together with their replication offsets, list of connected replicas and so forth."
        }
      ]
    },
    {
      "claim_text": "The ROLE command was added in Redis 2.8.12.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages do not mention when the ROLE command was added.",
      "citations": []
    }
  ]
}
